diagram "Services"
components {
  node server "Server" {
    component api "API" stereotype=service archRef=db {
      provides IOrders
      requires IPay
    }
    component pay "Pay" {
      provides IPay
    }
  }
  artifact jar "app.jar"
  api ..> jar "deploys"
  jar -- api
}

