diagram "Shop schema"

table users {
  id uuid [pk]
  email varchar(255) [not null, unique]
  createdAt timestamptz [default: now()]
  bio text [note: "free text"]
}

table orders {
  id bigint [pk, increment]
  user_id int [ref: > users.id]
  status text [default: "'new'"]
  total numeric(10,2) [not null]
  indexes {
    (status, total) [name: "idx_status"]
  }
}

table order_items {
  order_id bigint [pk, ref: > orders.id]
  product_id int [pk, ref: > products.id]
  qty int [not null]
}

table products {
  id int [pk]
  name text [not null]
  indexes {
    name [unique]
  }
}

table audit_log {
  line text
}

enum status {
  new
  paid
}

